    for i, x in enumerate(string1):
        for j, y in enumerate(string2):
            if x == y:
                table[i+1][j+1] = table[i][j]+1
            else:
                table[i+1][j+1] = max(table[i+1][j], table[i][j+1])

    result = ""
    x, y = len(string1), len(string2)
    while x != 0 and y != 0:
